/**
 * @title A left and a right sidebar
 * @description Workspace navigation on the left, a calendar panel on the right (from 1024px). The left one collapses; the right one stays.
 * @route /notes
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { SidebarLeft } from "@/components/sidebar-left";
import { SidebarRight } from "@/components/sidebar-right";
import { SiteHeader } from "@/components/site-header";
import { PagePlaceholder } from "@/components/page-placeholder";

export default function Page() {
  return (
    <SidebarProvider>
      <SidebarLeft />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Personal life", href: "#" }, { label: "Weekly plan" }]} />
        <PagePlaceholder title="Weekly plan" />
      </SidebarInset>
      <SidebarRight />
    </SidebarProvider>
  );
}

"use client";
import { AudioWaveform, Calendar, Command, Home, Inbox, Search, Settings2, Sparkles } from "lucide-react";
import { Sidebar, SidebarContent, SidebarHeader, SidebarRail } from "@/components/ui/sidebar";
import { NavMain } from "@/components/nav-main";
import { TeamSwitcher } from "@/components/team-switcher";

const teams = [{ name: "Acme Inc", plan: "Enterprise", logo: Command }, { name: "Acme Labs", plan: "Startup", logo: AudioWaveform }];
const items = [
  { title: "Search", url: "#", icon: Search }, { title: "Ask AI", url: "#", icon: Sparkles }, { title: "Home", url: "#", icon: Home, isActive: true },
  { title: "Inbox", url: "#", icon: Inbox }, { title: "Calendar", url: "#", icon: Calendar }, { title: "Settings", url: "#", icon: Settings2 },
];

export function SidebarLeft() {
  return (
    <Sidebar label="Workspace">
      <SidebarHeader>
        <TeamSwitcher teams={teams} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Workspace" className="contents"><NavMain label="Workspace" items={items} /></nav>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { ChevronRight, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton,
  SidebarMenuSubItem, useDisclosure, useSidebar,
} from "@/components/ui/sidebar";

export type NavItem = { title: string; url: string; icon: LucideIcon; isActive?: boolean; items?: { title: string; url: string; isActive?: boolean }[] };

/** Main navigation: rows that open to show their pages. In the icon rail a row expands the sidebar first. */
export function NavMain({ label = "Platform", items }: { label?: string; items: NavItem[] }) {
  return (
    <SidebarGroup>
      <SidebarGroupLabel>{label}</SidebarGroupLabel>
      <SidebarMenu>
        {items.map((item) => (item.items?.length ? <NavMainGroup key={item.title} item={item} /> : (
          <SidebarMenuItem key={item.title}>
            <SidebarMenuButton href={item.url} isActive={item.isActive} tooltip={item.title}>
              <Icon name={item.icon} />
              <span>{item.title}</span>
            </SidebarMenuButton>
          </SidebarMenuItem>
        )))}
      </SidebarMenu>
    </SidebarGroup>
  );
}

function NavMainGroup({ item }: { item: NavItem }) {
  const d = useDisclosure(item.isActive);
  const { state, setOpen, isMobile } = useSidebar();
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        tooltip={item.title}
        {...d.triggerProps}
        onClick={() => { if (state === "collapsed" && !isMobile) { setOpen(true); d.setOpen(true); } else d.triggerProps.onClick(); }}
      >
        <Icon name={item.icon} />
        <span className="flex-1">{item.title}</span>
        <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 transition-transform" : "transition-transform"} />
      </SidebarMenuButton>
      <SidebarMenuSub {...d.contentProps}>
        {item.items!.map((sub) => (
          <SidebarMenuSubItem key={sub.title}>
            <SidebarMenuSubButton href={sub.url} isActive={sub.isActive}><span>{sub.title}</span></SidebarMenuSubButton>
          </SidebarMenuSubItem>
        ))}
      </SidebarMenuSub>
    </SidebarMenuItem>
  );
}

"use client";
import { useState } from "react";
import { ChevronsUpDown, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

export type Team = { name: string; plan: string; logo: LucideIcon };

/** Workspace switcher at the top of the sidebar. */
export function TeamSwitcher({ teams }: { teams: Team[] }) {
  const { isMobile, state } = useSidebar();
  const [active, setActive] = useState(teams[0]);
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label="Switch workspace"
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "bottom-start"}
          items={[
            ...teams.map((t) => ({ label: t.name, onSelect: () => setActive(t) })),
            { label: "Add workspace", icon: "plus" as const, separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={active.name}>
              <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand">
                <Icon name={active.logo} size={16} />
              </span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{active.name}</span>
                <span className="truncate text-caption-default">{active.plan}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import { Button } from "@/components/ui/button";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader } from "@/components/ui/sidebar";
import { Calendars } from "@/components/calendars";
import { NavUser } from "@/components/nav-user";

/** Always open from 1024px; hidden below. */
export function SidebarRight() {
  return (
    <aside aria-label="Calendar" className="sticky top-0 hidden h-svh border-s border-line-default lg:flex">
      <Sidebar collapsible="none" className="w-[320px]">
        <SidebarHeader className="border-b border-line-default">
          <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
        </SidebarHeader>
        <SidebarContent>
          <Calendars />
        </SidebarContent>
        <SidebarFooter className="border-t border-line-default">
          <Button variant="secondary" leadingIcon="plus" className="w-full">New calendar</Button>
        </SidebarFooter>
      </Sidebar>
    </aside>
  );
}

"use client";
import { useState } from "react";
import { ChevronRight } from "lucide-react";
import { Calendar } from "@/components/ui/date";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, useDisclosure } from "@/components/ui/sidebar";

const groups = [
  { name: "My calendars", items: ["Personal", "Work", "Family"] },
  { name: "Favorites", items: ["Holidays", "Birthdays"] },
  { name: "Other", items: ["Travel", "Reminders", "Deadlines"] },
];
const dot = ["bg-brand", "bg-cat-teal-solid", "bg-cat-amber-solid", "bg-cat-red-solid", "bg-cat-lime-solid", "bg-cat-green-solid", "bg-cat-sky-solid", "bg-cat-orange-solid"];

function CalendarGroup({ name, items, offset }: { name: string; items: string[]; offset: number }) {
  const d = useDisclosure(true);
  const [on, setOn] = useState<Record<string, boolean>>(() => Object.fromEntries(items.map((i, k) => [i, k < 2])));
  return (
    <SidebarGroup className="py-1">
      <h3>
        <button type="button" {...d.triggerProps} className="flex h-8 w-full items-center justify-between rounded-control px-2 text-label-small text-fg-primary hover:bg-neutral-hover focus-visible:focus-ring">
          {name}
          <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 text-icon-secondary transition-transform" : "text-icon-secondary transition-transform"} />
        </button>
      </h3>
      <SidebarGroupContent {...d.contentProps}>
        <ul className="flex flex-col">
          {items.map((it, k) => (
            <li key={it}>
              <label className="flex h-8 cursor-pointer items-center gap-2 rounded-control px-2 text-body-small hover:bg-neutral-hover has-focus-visible:focus-ring">
                <input type="checkbox" checked={on[it]} onChange={(e) => setOn((o) => ({ ...o, [it]: e.target.checked }))} className="size-4 accent-[var(--ds-color-bg-brand)] outline-none" />
                <span aria-hidden className={`size-2 rounded-full ${dot[(offset + k) % dot.length]}`} />
                {it}
              </label>
            </li>
          ))}
        </ul>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/** A month calendar and a list of calendars you can show or hide. */
export function Calendars() {
  const [date, setDate] = useState<Date | undefined>(undefined);
  return (
    <>
      <div className="flex justify-center px-2 [&>div]:border-0 [&>div]:shadow-none [&>div]:bg-transparent">
        <Calendar value={date} onChange={setDate} />
      </div>
      <div role="separator" className="mx-3 h-px bg-line-default" />
      <section aria-label="Calendars">
        {groups.map((g, i) => <CalendarGroup key={g.name} {...g} offset={i * 3} />)}
      </section>
    </>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

/** Stand-in content for a page. Replace it with your own. */
export function PagePlaceholder({ title }: { title: string }) {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
      <h1 className="text-heading-h2">{title}</h1>
      <div aria-hidden className="grid gap-4 md:grid-cols-3">
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
      </div>
      <div aria-hidden className="min-h-96 flex-1 rounded-container bg-surface-subtle" />
    </div>
  );
}
